//! Data Designer parity with the Python adapter (tests/fixtures/datadesigner/dd_golden.json, generated by the Python
//! DataDesignerAdapter with gen_dd_golden.py):
//!   * providers(), aliases() and the show_config text over hundreds of yaml variants (same values, same exceptions);
//!   * the dataset copies of a full `create` run, byte for byte: the user's csv / jsonl / json copy, records.jsonl,
//!     the parquet batches copied, the verdict and record count, the 0600 modes.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

#[path = "datadesigner_helpers.rs"]
mod helpers;

use std::path::Path;
use std::sync::Arc;

use base64::Engine as _;
use helpers::*;
use nemo_console::adapters::base::{AdapterError, SystemAdapter};
use nemo_console::services::pyfmt::float_repr;
use serde_json::{Value, json};

fn raised(e: &AdapterError) -> Value {
    json!({"raised": {"class": e.py_class(), "message": e.to_string()}})
}

/// `(<any dir>/.data-designer/` -> `(CFG/.data-designer/` in the show_config header lines.
fn cfg_path_norm(v: &Value) -> Value {
    let re = regex::Regex::new(r"\(/[^()]*/\.data-designer/").unwrap();
    match v {
        Value::Array(a) => Value::Array(
            a.iter()
                .map(|x| match x {
                    Value::String(s) => {
                        Value::String(re.replace(s, "(CFG/.data-designer/").into_owned())
                    }
                    other => other.clone(),
                })
                .collect(),
        ),
        other => other.clone(),
    }
}

fn golden() -> Value {
    let p = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/datadesigner/dd_golden.json"
    );
    serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap()
}

fn b64(s: &str) -> Vec<u8> {
    base64::engine::general_purpose::STANDARD.decode(s).unwrap()
}

#[tokio::test]
async fn test_yaml_config_views_match_the_python_adapter() {
    let g = golden();
    let cases = g["yaml"].as_array().unwrap();
    assert!(cases.len() > 300);
    let f = Fx::new().await;
    let cfg = f.path().join("home/.data-designer");
    std::fs::create_dir_all(&cfg).unwrap();
    let a = f.adapter_with(
        &standard_runner(),
        Opts {
            providers: false,
            ..Opts::default()
        },
    );
    let mut failures = Vec::new();
    for c in cases {
        std::fs::write(
            cfg.join("model_providers.yaml"),
            c["providers_yaml"].as_str().unwrap(),
        )
        .unwrap();
        std::fs::write(
            cfg.join("model_configs.yaml"),
            c["configs_yaml"].as_str().unwrap(),
        )
        .unwrap();
        let providers = match a.providers() {
            Ok(ps) => Value::Array(
                ps.iter()
                    .map(|p| json!({"name": p.name, "endpoint": p.endpoint, "provider_type": p.provider_type}))
                    .collect(),
            ),
            Err(e) => raised(&e),
        };
        let r = |x: Option<f64>| x.map_or(Value::Null, |v| Value::from(float_repr(v)));
        let aliases = match a.aliases() {
            Ok(xs) => Value::Array(
                xs.iter()
                    .map(|x| {
                        json!({"alias": x.alias, "model": x.model, "provider": x.provider,
                               "generation_type": x.generation_type, "temperature": r(x.temperature),
                               "top_p": r(x.top_p), "max_tokens": r(x.max_tokens)})
                    })
                    .collect(),
            ),
            Err(e) => raised(&e),
        };
        let dump = match a.config_dump() {
            Ok(lines) => json!(lines),
            Err(e) => raised(&e),
        };
        for (what, got) in [
            ("providers", providers),
            ("aliases", aliases),
            ("dump", dump),
        ] {
            // the dump names the config files: only the temp dir differs (normalised, nothing else)
            let (got, want) = (cfg_path_norm(&got), cfg_path_norm(&c[what]));
            if got != want {
                failures.push(format!(
                    "{what} of {:?} / {:?}\n  want {want}\n  got  {got}",
                    c["providers_yaml"], c["configs_yaml"]
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} differences:\n{}",
        failures.len(),
        failures
            .iter()
            .take(12)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}

/// The generator's fake runner: create writes metadata listing N batches; the exporter writes the case's bytes.
fn copy_runner(case: &Value) -> Arc<FakeRunner> {
    let r = FakeRunner::new();
    r.on(&[LAUNCHER, "--version"], ok("0.9.3\n"));
    let batches = case["batches"].as_array().unwrap().clone();
    let records = case["records"].clone();
    let n = batches.len();
    r.on(
        &[LAUNCHER, "create"],
        func(move |argv| {
            let at = |f: &str| argv[argv.iter().position(|a| a == f).unwrap() + 1].clone();
            let out = Path::new(&at("--artifact-path")).join(at("--dataset-name"));
            std::fs::create_dir_all(out.join("parquet-files")).unwrap();
            for i in 0..n {
                let mut b = b"PAR1".to_vec();
                b.extend(std::iter::repeat_n(u8::try_from(i).unwrap(), 7));
                std::fs::write(out.join("parquet-files").join(format!("batch_{i:05}.parquet")), b).unwrap();
            }
            let md = json!({"actual_num_records": records,
                            "file_paths": {"parquet-files": (0..n).map(|i| format!("parquet-files/batch_{i:05}.parquet")).collect::<Vec<_>>()}});
            std::fs::write(out.join("metadata.json"), md.to_string()).unwrap();
            res("", 0, "")
        }),
    );
    r.on(
        &[EXPORTER],
        func(move |argv| {
            let stem = Path::new(&argv[1])
                .file_stem()
                .unwrap()
                .to_string_lossy()
                .into_owned();
            let i: usize = stem.split('_').nth(1).unwrap().parse().unwrap();
            let ext = Path::new(&argv[2])
                .extension()
                .unwrap()
                .to_string_lossy()
                .into_owned();
            match batches[i].get(&ext).and_then(Value::as_str) {
                Some(data) => {
                    std::fs::write(&argv[2], b64(data)).unwrap();
                    res("", 0, "")
                }
                None => res("", 2, &format!("no {ext}")),
            }
        }),
    );
    r
}

// several mock routers in one test: wiremock's drop blocks on the runtime, so not a current-thread one
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn test_dataset_copies_are_byte_for_byte_python() {
    let g = golden();
    let cases = g["copies"].as_array().unwrap();
    assert_eq!(cases.len(), 24);
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let want = &c["out"];
        let f = Fx::new().await;
        let a = f.adapter(&copy_runner(c));
        let res = a
            .run_action(
                "create",
                &params(
                    json!({"script": "reviews_smoke.py", "num_records": 5, "format": c["format"],
                               "dataset_name": "ds", "destination_subdir": "out"}),
                ),
            )
            .await
            .unwrap();
        assert!(res.ok, "{name}: {}", res.output);
        let rid = started_run_id(&res.output);
        finish(&a).await;
        let meta = run_json(&a, &rid);
        assert_eq!(meta["verdict"], want["verdict"], "{name}");
        assert_eq!(meta["records"], want["records"], "{name}");
        assert_eq!(
            meta.get("batches").cloned().unwrap_or(Value::Null),
            want["batches"],
            "{name}"
        );
        let root = datasets_root(&a).join("out");
        let target = root.join(format!("ds.{}", c["format"].as_str().unwrap()));
        match want["target"].as_str() {
            Some(t) => {
                assert_eq!(
                    std::fs::read(&target).unwrap(),
                    b64(t),
                    "{name}: user copy bytes"
                );
                if want["target_mode"] == "0o600" {
                    assert_eq!(mode_of(&target), 0o600, "{name}");
                } else {
                    // created with 0o666 & ~umask and left so after a failed conversion, like Python
                    let probe = f.path().join("umask-probe");
                    std::fs::write(&probe, "").unwrap();
                    assert_eq!(mode_of(&target), mode_of(&probe), "{name}");
                }
            }
            None => assert!(!target.is_file() || c["format"] == "parquet", "{name}"),
        }
        let rec = a.runs_dir().join(&rid).join("records.jsonl");
        match want["records_jsonl"].as_str() {
            Some(t) => {
                assert_eq!(
                    std::fs::read(&rec).unwrap(),
                    b64(t),
                    "{name}: records.jsonl bytes"
                );
                // The golden was recorded under umask 002 (0o666 & ~0o002 = 0o664). Python creates the file with
                // 0o666 & ~umask, so compare with a probe file made under this process's umask, as for the copy above.
                let want_mode = want["records_mode"].as_str().unwrap();
                if want_mode == "0o600" {
                    assert_eq!(mode_of(&rec), 0o600, "{name}");
                } else {
                    assert_eq!(
                        want_mode, "0o664",
                        "{name}: golden recorded under an unexpected umask"
                    );
                    let probe = f.path().join("umask-probe-records");
                    std::fs::write(&probe, "").unwrap();
                    assert_eq!(mode_of(&rec), mode_of(&probe), "{name}");
                }
            }
            None => assert!(!rec.exists(), "{name}"),
        }
        let mut files: Vec<String> = std::fs::read_dir(&root)
            .map(|rd| {
                rd.map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
                    .collect()
            })
            .unwrap_or_default();
        files.sort();
        assert_eq!(json!(files), want["dest_files"], "{name}");
        if c["format"] == "parquet" {
            for f in &files {
                let mut b = b"PAR1".to_vec();
                let i: u8 = f[6..11].parse().unwrap();
                b.extend(std::iter::repeat_n(i, 7));
                assert_eq!(std::fs::read(root.join(f)).unwrap(), b, "{name}: {f}");
            }
        }
    }
}
